import { useCallback, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { TextField } from "@/shared/ui/controls/Field";
import { InlineError } from "@/shared/ui/feedback/InlineError";
import { TracePlayer } from "@/features/algorithms/viz/TracePlayer";

interface VizExample {
  factory: () => Generator<unknown>;
  renderers?: Record<string, unknown>;
  input: { default: string; hint?: string; parse: (text: string) => unknown; make: (parsed: unknown) => Promise<() => Generator<unknown>> };
  source?: string;
}

export function VizStage({
  viz = {
    factory: function* () { yield { structure: "array", data: [3, 1, 4, 1, 5] }; },
    input: { default: "3, 1, 4, 1, 5", hint: "comma-separated numbers", parse: (t: string) => t, make: async () => (function* () { yield { structure: "array", data: [3, 1, 4, 1, 5] }; })() },
  },
  implName = "Bubble Sort",
  onBack = () => {},
}: { viz?: VizExample; implName?: string; onBack?: () => void }) {
  const [text, setText] = useState(viz.input.default);
  const [error, setError] = useState<string | null>(null);
  const [factory, setFactory] = useState<() => Generator<any>>(() => viz.factory as () => Generator<any>);

  const run = useCallback(async () => {
    let parsed: unknown;
    try {
      parsed = viz.input.parse(text);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      return;
    }
    try {
      const nextFactory = await viz.input.make(parsed);
      setFactory(() => nextFactory as () => Generator<any>);
      setError(null);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, [text, viz]);

  return (
    <Box
      className="algo-viz-stage"
      role="group"
      aria-label={`Visualization — ${implName}`}
      onMouseDown={(e) => e.stopPropagation()}
      onClick={(e) => e.stopPropagation()}
      style={{
        position: "relative",
        display: "flex",
        flexDirection: "column",
        background: "var(--bg-canvas, var(--bg))",
        cursor: "default",
        minHeight: 320,
      }}
    >
      <Row align="center" gap={12} className="algo-viz-stage-head">
        <Button variant="ghost" onClick={onBack}>
          ← Back to graph
        </Button>
        <Text as="span" mono size={9.5} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".08em" }}>Visualization</Text>
        <Text weight={600} size={13}>
          {implName}
        </Text>
      </Row>

      <Box className="algo-viz-stage-body">
        <TracePlayer factory={factory} renderers={viz.renderers as any} fps={4} autoPlay loop controls source={viz.source} />
      </Box>

      <Stack gap={8} className="algo-viz-stage-state">
        <Row gap={8} align="end">
          <Box style={{ flex: 1, minWidth: 0 }}>
            <TextField
              label="Your input"
              value={text}
              onChange={setText}
              hint={viz.input.hint}
              spellCheck={false}
              autoComplete="off"
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  void run();
                }
              }}
            />
          </Box>
          <Button onClick={() => void run()}>Run</Button>
        </Row>
        {error ? (
          <InlineError>{error}</InlineError>
        ) : (
          <Text size={11} tone="dim">
            Edit the input and Run to visualize your own state.
          </Text>
        )}
      </Stack>
    </Box>
  );
}
